!function(){"use strict";var e=document.getElementById("workerRequestForm");if(e){var t=document.getElementById("wrSubmitBtn"),r=document.getElementById("wrSuccess"),n=document.getElementById("wrError");e.addEventListener("submit",async function(a){a.preventDefault(),t.disabled=!0,t.innerHTML='<i class="fas fa-spinner fa-spin"></i> جارٍ الإرسال...',r.style.display="none",n.style.display="none";var i=document.getElementById("wrFullName").value.trim(),o=document.getElementById("wrPhone").value.trim(),l=document.getElementById("wrWorkerType").value.trim(),s=document.getElementById("wrWorkerCount").value||"1",u=document.getElementById("wrSalary").value.trim(),m=document.getElementById("wrWorkTime").value.trim(),d=document.getElementById("wrLocation").value.trim(),y=document.getElementById("wrStartDate").value,c=document.getElementById("wrDescription").value.trim(),p={full_name:i,phone:o,service_type:"worker_request",message:JSON.stringify({worker_type:l,worker_type_label:l,worker_count:s,salary:u,work_time:m,location:d,start_date:y||null,description:c})};try{var w=SITE.supabase.url,f=SITE.supabase.anonKey;if(!w||!f||"YOUR_SUPABASE_URL"===w)throw new Error("Supabase not configured");var v=await fetch(w+"/rest/v1/service_requests",{method:"POST",headers:{"Content-Type":"application/json",apikey:f,Authorization:"Bearer "+f,Prefer:"return=minimal","X-Requested-With":"XMLHttpRequest"},body:JSON.stringify(p)});if(!v.ok){var E=await v.text();throw new Error("Submit failed: "+E)}r.style.display="flex",e.reset(),setTimeout(function(){r.style.display="none"},5e3)}catch(e){console.error("Worker request error:",e),n.style.display="flex"}finally{t.disabled=!1,t.innerHTML='<i class="fas fa-paper-plane"></i> إرسال الطلب'}})}}();